type Role = 'manager' | 'lawyer' | 'employee';
type Profile = { id: string; office_id: string | null; role: Role; display_name: string; email: string | null; is_active: boolean };
type Office = { id: string; name: string; phone: string | null; email: string | null };
type Client = { id: string; full_name: string; kind: string; phone: string | null; email: string | null; national_id: string | null; notes: string | null; created_at: string };
type ClientCommunication = { id: string; client_id: string; channel: string; subject: string; content: string | null; occurred_at: string; created_by: string | null };
type LegalCase = { id: string; case_number: string; title: string; client_id: string; responsible_lawyer_id: string | null; type: string; status: string; court_name: string | null; opening_date: string | null; description: string | null };
type Hearing = { id: string; case_id: string; hearing_at: string; court_name: string | null; court_room: string | null; status: string; outcome: string | null; reminder_at: string | null };
type Task = { id: string; title: string; description: string | null; assigned_to: string | null; priority: string; status: string; due_at: string | null; case_id: string | null };
type OfficeDocument = { id: string; file_name: string; category: string; case_id: string | null; client_id: string | null; created_at: string };
type LegalSource = { id: string; title: string; official_number: string | null; source_type: string; source_url: string; issued_on: string | null };
type Page = 'dashboard' | 'cases' | 'hearings' | 'clients' | 'tasks' | 'documents' | 'team' | 'assistant' | 'sources' | 'reports';
type AssistantResult = { summary: string; legalIssues: { issue: string; analysis: string }[]; proposedDefences: { heading: string; argument: string; strength: string }[]; clarificationQuestions: string[]; draft: string; limitations: string; citations: { id: string; title: string; url: string; officialNumber: string | null; excerpt: string }[]; similarPrecedents: { id: string; courtName: string; referenceNumber: string | null; decidedOn: string | null; title: string; summary: string; url: string; relevanceScore: number }[] };

const nav: { id: Page; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard }, { id: 'cases', label: 'القضايا', icon: BriefcaseBusiness },
  { id: 'hearings', label: 'الجلسات', icon: CalendarClock }, { id: 'clients', label: 'العملاء', icon: Users },
  { id: 'tasks', label: 'المهام', icon: ClipboardCheck }, { id: 'documents', label: 'المستندات', icon: FileText },
  { id: 'team', label: 'فريق المكتب', icon: UserPlus }, { id: 'assistant', label: 'المساعد القانوني', icon: Sparkles },
  { id: 'sources', label: 'المصادر القانونية', icon: BookOpenText }, { id: 'reports', label: 'التقارير', icon: FolderKanban },
];

const tone = (value?: string | null) => ({ active: 'bg-emerald-50 text-emerald-700 border-emerald-200', new: 'bg-blue-50 text-blue-700 border-blue-200', on_hold: 'bg-amber-50 text-amber-700 border-amber-200', appeal: 'bg-violet-50 text-violet-700 border-violet-200', closed: 'bg-slate-100 text-slate-600 border-slate-200', scheduled: 'bg-indigo-50 text-indigo-700 border-indigo-200', completed: 'bg-emerald-50 text-emerald-700 border-emerald-200' }[value ?? ''] ?? 'bg-slate-100 text-slate-600 border-slate-200');
const inputClass = 'w-full h-10 rounded-lg border bg-background px-3 text-sm';
const dateValue = (offset = 1) => new Date(Date.now() + offset * 86400000).toISOString().slice(0, 16);

function Brand({ compact = false }: { compact?: boolean }) { return <div className="flex items-center gap-3"><div className="h-10 w-10 rounded-xl grid place-items-center bg-[#0d3b36] text-[#e8c377] shadow-lg shadow-[#0d3b36]/20"><Scale className="h-5 w-5" /></div>{!compact && <div><p className="font-bold leading-none text-[#153a36]">ميزان المكتب</p><p className="text-[11px] text-muted-foreground mt-1">إدارة قانونية ذكية</p></div>}</div>; }
function Title({ eyebrow, title, text, action }: { eyebrow: string; title: string; text: string; action?: ReactNode }) { return <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between mb-6"><div><p className="text-xs tracking-[.15em] font-bold text-[#b58524]">{eyebrow}</p><h1 className="text-2xl sm:text-3xl font-bold mt-1 text-[#153a36]">{title}</h1><p className="text-sm leading-6 text-muted-foreground mt-2 max-w-2xl">{text}</p></div>{action}</div>; }
function Empty({ icon: Icon, title, text, action }: { icon: typeof BriefcaseBusiness; title: string; text: string; action?: ReactNode }) { return <div className="border border-dashed rounded-2xl py-12 text-center bg-white/50"><div className="h-12 w-12 mx-auto grid place-items-center rounded-xl bg-[#edf4f1] text-[#1b6258]"><Icon className="h-6 w-6" /></div><p className="font-semibold mt-4 text-[#153a36]">{title}</p><p className="text-sm text-muted-foreground mt-1 px-5">{text}</p>{action && <div className="mt-5">{action}</div>}</div>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="fixed inset-0 bg-[#092a26]/45 backdrop-blur-sm z-50 p-4 grid place-items-center" dir="rtl"><Card className="w-full max-w-2xl max-h-[94vh] overflow-y-auto border-0 shadow-2xl"><CardHeader className="sticky top-0 bg-card/95 z-10 border-b"><div className="flex justify-between items-center"><CardTitle className="text-xl text-[#153a36]">{title}</CardTitle><button className="p-2 rounded-lg hover:bg-muted" onClick={onClose}><X className="h-4 w-4" /></button></div></CardHeader><CardContent className="pt-6">{children}</CardContent></Card></div>; }

function Login({ done }: { done: () => Promise<void> }) {
  const [isNew, setIsNew] = useState(false); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [name, setName] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); const { data, error } = isNew ? await supabase.auth.signUp({ email, password, options: { data: { full_name: name } } }) : await supabase.auth.signInWithPassword({ email, password }); setBusy(false); if (error) return toast.error(error.message); if (isNew && !data.session) return toast.success('تم إنشاء الحساب. راجع بريدك لتأكيد التسجيل.'); await done(); toast.success('تم تسجيل الدخول.'); };
  return <main dir="rtl" className="min-h-screen w-full max-w-full overflow-x-hidden bg-[#f4f7f5] grid lg:grid-cols-2"><section className="hidden lg:flex min-w-0 bg-[#103b35] text-white p-14 relative overflow-hidden flex-col justify-between"><div className="absolute inset-0 opacity-20" style={{ backgroundImage: 'radial-gradient(circle at 15% 20%, #e8c377 0, transparent 23%),radial-gradient(circle at 80% 80%, #67a99c 0, transparent 30%)' }} /><div className="relative"><Brand /><div className="mt-32 max-w-xl"><p className="text-[#e8c377]">منظومة عربية لمكاتب المحاماة في قطر</p><h1 className="text-5xl leading-tight font-bold mt-4">كل قضية في مسار واضح، وكل مذكرة مسنودة بمصدر.</h1><p className="text-emerald-50/80 mt-6 leading-8">إدارة القضايا والجلسات والعملاء والمستندات وفريق المكتب، مع مساحة ذكية لصياغة المذكرات ومراجعة مراجعها.</p></div></div><p className="relative text-sm text-emerald-50/70">صلاحيات متعددة الأدوار · عزل آمن للبيانات · مصادر قانونية موثقة</p></section><section className="grid min-w-0 place-items-center p-5"><div className="w-full max-w-md mx-auto min-w-0"><div className="lg:hidden mb-10"><Brand /></div><Card className="w-full min-w-0 border-0 shadow-xl shadow-[#0d3b36]/10"><CardHeader><CardTitle className="text-2xl text-[#153a36]">{isNew ? 'ابدأ مساحة مكتبك' : 'مرحباً بعودتك'}</CardTitle><CardDescription>{isNew ? 'أنشئ حسابك ثم جهّز بيانات المكتب.' : 'سجل الدخول للوصول إلى إدارة المكتب.'}</CardDescription></CardHeader><CardContent><form onSubmit={submit} className="space-y-4">{isNew && <div className="space-y-2"><Label>الاسم الكامل</Label><Input value={name} onChange={e => setName(e.target.value)} required placeholder="الاسم الكامل" /></div>}<div className="space-y-2"><Label>البريد الإلكتروني</Label><Input dir="ltr" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="name@office.qa" /></div><div className="space-y-2"><Label>كلمة المرور</Label><Input dir="ltr" type="password" value={password} onChange={e => setPassword(e.target.value)} required minLength={8} /></div><Button className="w-full h-11 bg-[#0d3b36] hover:bg-[#164d45]" disabled={busy}>{busy && <Loader2 className="h-4 w-4 animate-spin" />}{isNew ? 'إنشاء الحساب' : 'تسجيل الدخول'}</Button></form><p className="text-center text-sm text-muted-foreground mt-5">{isNew ? 'لديك حساب؟' : 'ليس لديك حساب؟'} <button className="font-semibold text-[#1b6258]" onClick={() => setIsNew(!isNew)}>{isNew ? 'تسجيل الدخول' : 'إنشاء حساب'}</button></p></CardContent></Card><p className="text-xs text-muted-foreground text-center mt-5 leading-5">النتائج القانونية المولدة هي مسودات للمراجعة المهنية وليست بديلاً عن المحامي المختص.</p></div></section></main>;
}

export default function Home() {
  const [session, setSession] = useState<Session | null>(null); const [profile, setProfile] = useState<Profile | null>(null); const [office, setOffice] = useState<Office | null>(null); const [ready, setReady] = useState(false); const [page, setPage] = useState<Page>('dashboard'); const [mobileMenu, setMobileMenu] = useState(false); const [modal, setModal] = useState<'client' | 'case' | 'hearing' | 'task' | 'doc' | 'invite' | 'communication' | 'outcome' | null>(null);
  const [clients, setClients] = useState<Client[]>([]); const [communications, setCommunications] = useState<ClientCommunication[]>([]); const [selectedClientId, setSelectedClientId] = useState(''); const [selectedHearing, setSelectedHearing] = useState<Hearing | null>(null); const [cases, setCases] = useState<LegalCase[]>([]); const [hearings, setHearings] = useState<Hearing[]>([]); const [tasks, setTasks] = useState<Task[]>([]); const [docs, setDocs] = useState<OfficeDocument[]>([]); const [team, setTeam] = useState<Profile[]>([]); const [sources, setSources] = useState<LegalSource[]>([]); const [search, setSearch] = useState(''); const [reportRange, setReportRange] = useState('all'); const [searchResults, setSearchResults] = useState<{ id: string; heading: string | null; body: string; legal_sources: { title: string; source_url: string } | null }[]>([]); const [assistantText, setAssistantText] = useState(''); const [assistantCase, setAssistantCase] = useState(''); const [assistantResult, setAssistantResult] = useState<AssistantResult | null>(null);
  const generate = trpc.legalAssistant.generate.useMutation();
  const load = async (incoming?: Session | null) => {
    const active = incoming ?? (await supabase.auth.getSession()).data.session; setSession(active ?? null); if (!active) { setProfile(null); setOffice(null); setReady(true); return; }
    setReady(false); const id = active.user.id; let { data: own } = await supabase.from('profiles').select('id,office_id,role,display_name,email,is_active').eq('id', id).maybeSingle(); if (!own) { await new Promise(resolve => setTimeout(resolve, 500)); ({ data: own } = await supabase.from('profiles').select('id,office_id,role,display_name,email,is_active').eq('id', id).maybeSingle()); }
    setProfile(own as Profile | null); if (!own?.office_id) { setOffice(null); setReady(true); return; } const all = await Promise.all([
      supabase.from('offices').select('id,name,phone,email').eq('id', own.office_id).single(), supabase.from('clients').select('id,full_name,kind,phone,email,national_id,notes,created_at').order('created_at', { ascending: false }),
      supabase.from('legal_cases').select('id,case_number,title,client_id,responsible_lawyer_id,type,status,court_name,opening_date,description').order('created_at', { ascending: false }), supabase.from('hearings').select('id,case_id,hearing_at,court_name,court_room,status,outcome,reminder_at').order('hearing_at'),
      supabase.from('tasks').select('id,title,description,assigned_to,priority,status,due_at,case_id').order('due_at'), supabase.from('documents').select('id,file_name,category,case_id,client_id,created_at').order('created_at', { ascending: false }),
      supabase.from('profiles').select('id,office_id,role,display_name,email,is_active').order('display_name'), supabase.from('legal_sources').select('id,title,official_number,source_type,source_url,issued_on').order('source_type').order('title'),
      supabase.from('client_communications').select('id,client_id,channel,subject,content,occurred_at,created_by').order('occurred_at', { ascending: false }),
    ]); setOffice(all[0].data as Office | null); setClients((all[1].data ?? []) as Client[]); setCases((all[2].data ?? []) as LegalCase[]); setHearings((all[3].data ?? []) as Hearing[]); setTasks((all[4].data ?? []) as Task[]); setDocs((all[5].data ?? []) as OfficeDocument[]); setTeam((all[6].data ?? []) as Profile[]); setSources((all[7].data ?? []) as LegalSource[]); setCommunications((all[8].data ?? []) as ClientCommunication[]); setReady(true);
  };
  useEffect(() => { load(); const { data } = supabase.auth.onAuthStateChange((_event, changed) => { setTimeout(() => load(changed), 0); }); return () => data.subscription.unsubscribe(); }, []);
  const manager = can(profile?.role, 'manage_office'); const practitioner = can(profile?.role, 'create_case'); const canRecordCommunication = can(profile?.role, 'record_communication'); const canCompleteTask = (task: Task) => manager || task.assigned_to === profile?.id; const activeCases = cases.filter(item => ['new', 'active', 'on_hold', 'appeal'].includes(item.status)); const upcoming = hearings.filter(item => item.status === 'scheduled' && new Date(item.hearing_at) > new Date()).slice(0, 5); const dueReminders = hearings.filter(item => isReminderDue(item.reminder_at, item.status)); const overdue = tasks.filter(item => isOverdue(item.due_at, item.status)); const caseById = (id?: string | null) => cases.find(item => item.id === id); const clientById = (id?: string | null) => clients.find(item => item.id === id); const memberById = (id?: string | null) => team.find(item => item.id === id); const rangeDays = reportRange === '30' ? 30 : reportRange === '90' ? 90 : reportRange === '365' ? 365 : undefined; const reportCases = cases.filter(item => isWithinDays(item.opening_date, rangeDays));
  const charts = useMemo(() => ({ status: Object.entries(reportCases.reduce<Record<string, number>>((a, item) => { const key = caseStatusLabel(item.status); a[key] = (a[key] ?? 0) + 1; return a; }, {})).map(([name, value]) => ({ name, value })), type: Object.entries(reportCases.reduce<Record<string, number>>((a, item) => { const key = ({ criminal: 'جنائية', civil: 'مدنية', commercial: 'تجارية', labor: 'عمالية', family: 'أسرة', administrative: 'إدارية' } as Record<string, string>)[item.type] ?? 'أخرى'; a[key] = (a[key] ?? 0) + 1; return a; }, {})).map(([name, value]) => ({ name, value })) }), [reportCases]);
  const createOffice = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const { error } = await supabase.rpc('create_office_with_manager', { p_name: data.get('name') as string, p_phone: data.get('phone') || null, p_email: data.get('email') || null, p_address: null }); if (error) return toast.error(error.message); await load(); };
  const add = async (kind: NonNullable<typeof modal>, event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!practitioner && (kind === 'client' || kind === 'doc')) return toast.error('هذه العملية متاحة للمحامي ومدير المكتب فقط.'); const data = new FormData(event.currentTarget); let error: { message: string } | null = null;
    if (kind === 'client') ({ error } = await supabase.from('clients').insert({ office_id: profile!.office_id!, full_name: data.get('name') as string, kind: data.get('kind') as string, phone: data.get('phone') || null, email: data.get('email') || null, national_id: data.get('id_number') || null, notes: data.get('notes') || null, created_by: profile!.id }));
    if (kind === 'case') ({ error } = await supabase.from('legal_cases').insert({ office_id: profile!.office_id!, case_number: data.get('number') as string, title: data.get('title') as string, client_id: data.get('client') as string, responsible_lawyer_id: data.get('lawyer') || profile!.id, type: data.get('type') as string, court_name: data.get('court') || null, description: data.get('description') || null, created_by: profile!.id }));
    if (kind === 'hearing') { const at = new Date(data.get('at') as string); ({ error } = await supabase.from('hearings').insert({ office_id: profile!.office_id!, case_id: data.get('case') as string, hearing_at: at.toISOString(), court_name: data.get('court') || null, court_room: data.get('room') || null, hearing_type: data.get('type') || null, reminder_at: new Date(at.getTime() - 86400000).toISOString(), notes: data.get('notes') || null, created_by: profile!.id })); }
    if (kind === 'task') ({ error } = await supabase.from('tasks').insert({ office_id: profile!.office_id!, title: data.get('title') as string, description: data.get('description') || null, case_id: data.get('case') || null, assigned_to: data.get('member') || profile!.id, priority: data.get('priority') as string, due_at: data.get('due') ? new Date(data.get('due') as string).toISOString() : null, created_by: profile!.id }));
    if (kind === 'invite') { const { data: invitation, error: inviteError } = await supabase.from('office_invitations').upsert({ office_id: profile!.office_id!, email: data.get('email') as string, role: data.get('role') as string, created_by: profile!.id }, { onConflict: 'office_id,email' }).select('invitation_token').single(); error = inviteError; if (!error && invitation?.invitation_token) { await navigator.clipboard?.writeText(`${window.location.origin}/?invite=${invitation.invitation_token}`); toast.success('تم إنشاء رابط الدعوة ونسخه للحافظة.'); } else if (!error) { error = { message: 'تعذر إنشاء رابط الدعوة.' }; } }
    if (kind === 'doc') { const file = data.get('file') as File; if (!file?.name) return toast.error('اختر ملفاً أولاً.'); const path = `${profile!.office_id}/${Date.now()}-${file.name.replace(/[^\w.\-\u0600-\u06FF]/g, '_')}`; const upload = await supabase.storage.from('legal-documents').upload(path, file, { contentType: file.type }); if (upload.error) return toast.error(upload.error.message); ({ error } = await supabase.from('documents').insert({ office_id: profile!.office_id!, file_name: file.name, storage_path: path, mime_type: file.type || null, byte_size: file.size, category: data.get('category') as string, case_id: data.get('case') || null, client_id: data.get('client') || null, uploaded_by: profile!.id })); }
    if (error) return toast.error(error.message); setModal(null); await load(); toast.success(kind === 'task' ? 'تم إنشاء المهمة.' : 'تم الحفظ بنجاح.'); };
  const closeTask = async (task: Task) => { if (!canCompleteTask(task)) return toast.error('يمكنك إغلاق المهمة المسندة إليك فقط.'); const { error } = await supabase.from('tasks').update({ status: 'completed', completed_at: new Date().toISOString() }).eq('id', task.id); if (error) return toast.error(error.message); await load(); };
  const addCommunication = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const { error } = await supabase.from('client_communications').insert({ office_id: profile!.office_id!, client_id: data.get('client') as string, created_by: profile!.id, channel: data.get('channel') as string, subject: data.get('subject') as string, content: data.get('content') || null, occurred_at: new Date(data.get('occurred_at') as string).toISOString() }); if (error) return toast.error(error.message); setModal(null); await load(); toast.success('تم حفظ متابعة العميل.'); };
  const recordOutcome = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selectedHearing) return; const data = new FormData(event.currentTarget); const { error } = await supabase.from('hearings').update({ status: data.get('status') as string, outcome: data.get('outcome') as string }).eq('id', selectedHearing.id); if (error) return toast.error(error.message); setModal(null); setSelectedHearing(null); await load(); toast.success('تم تحديث نتيجة الجلسة.'); };
  const runSearch = async (term: string) => { setSearch(term); if (term.trim().length < 3) return setSearchResults([]); const { data, error } = await supabase.from('legal_source_sections').select('id,heading,body,legal_sources(title,source_url)').ilike('body', `%${term.trim()}%`).limit(6); if (error) return toast.error(error.message); const normalized = (data ?? []).map(item => ({ ...item, legal_sources: Array.isArray(item.legal_sources) ? item.legal_sources[0] ?? null : item.legal_sources })) as unknown as typeof searchResults; setSearchResults(normalized); };
  const runAssistant = async () => { if (!assistantText.trim()) return toast.error('أدخل وقائع القضية أو الطلب القانوني.'); try { const result = await generate.mutateAsync({ accessToken: session!.access_token, caseId: assistantCase && assistantCase !== 'none' ? assistantCase : undefined, request: assistantText, objective: 'draft' }); setAssistantResult(result as AssistantResult); toast.success('تم إعداد مسودة قابلة للمراجعة.'); } catch (error) { toast.error(error instanceof Error ? error.message : 'تعذر تنفيذ طلب المساعد.'); } };
  if (!ready) return <main className="min-h-screen grid place-items-center bg-[#f4f7f5]"><Loader2 className="animate-spin text-[#1b6258]" /></main>;
  if (!session) return <Login done={() => load()} />;
  if (!profile) return <main className="min-h-screen grid place-items-center"><Loader2 className="animate-spin" /></main>;
  if (!office) { const invitationToken = new URLSearchParams(window.location.search).get('invite'); const acceptInvitation = async () => { if (!invitationToken) return; const { error } = await supabase.rpc('accept_office_invitation', { p_token: invitationToken }); if (error) return toast.error(error.message); window.history.replaceState({}, '', window.location.pathname); await load(); toast.success('تم الانضمام إلى المكتب بنجاح.'); }; return <main dir="rtl" className="min-h-screen bg-[#f4f7f5] grid place-items-center p-5"><Card className="w-full max-w-xl border-0 shadow-xl"><CardHeader><Brand /><CardTitle className="text-2xl mt-7 text-[#153a36]">{invitationToken ? 'دعوة للانضمام إلى المكتب' : 'لنجهز مساحة مكتبك'}</CardTitle><CardDescription>{invitationToken ? 'سيتم تعيينك تلقائياً بالدور المحدد في الدعوة، ولا يمكنك تعديله من هذا الرابط.' : 'ستكون مدير المكتب ويمكنك بعد ذلك دعوة المحامين والموظفين.'}</CardDescription></CardHeader><CardContent>{invitationToken ? <div className="space-y-4"><div className="p-4 rounded-xl bg-[#edf4f1] text-sm leading-6 text-[#1b6258]">تحقق من أن هذا الحساب هو الحساب المقصود بالدعوة ثم أكمل الانضمام. سيُسجل الدور وفق صلاحية مدير المكتب.</div><Button onClick={acceptInvitation} className="w-full h-11 bg-[#0d3b36]">قبول الدعوة والانضمام</Button><div className="border-t pt-4"><p className="text-xs text-muted-foreground mb-3">لست مدعواً إلى مكتب؟ يمكنك إنشاء مكتب جديد بصفتك مديراً.</p><form onSubmit={createOffice} className="grid sm:grid-cols-2 gap-4"><div className="sm:col-span-2 space-y-2"><Label>اسم المكتب</Label><Input name="name" required placeholder="مكتب ... للمحاماة" /></div><div className="space-y-2"><Label>الهاتف</Label><Input name="phone" dir="ltr" /></div><div className="space-y-2"><Label>بريد المكتب</Label><Input name="email" dir="ltr" type="email" /></div><Button className="sm:col-span-2 h-11" variant="outline">إنشاء مكتب جديد</Button></form></div></div> : <form onSubmit={createOffice} className="grid sm:grid-cols-2 gap-4"><div className="sm:col-span-2 space-y-2"><Label>اسم المكتب</Label><Input name="name" required placeholder="مكتب ... للمحاماة" /></div><div className="space-y-2"><Label>الهاتف</Label><Input name="phone" dir="ltr" /></div><div className="space-y-2"><Label>بريد المكتب</Label><Input name="email" dir="ltr" type="email" /></div><Button className="sm:col-span-2 h-11 bg-[#0d3b36]">إنشاء المكتب</Button></form>}</CardContent></Card></main>; }
  const dashboard = <><Title eyebrow="مساحة العمل" title={`مرحباً، ${profile.display_name || 'زميلنا'}`} text="نظرة مركزة على القضايا والجلسات والمهام التي تحتاج متابعة اليوم." action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('case')}><Plus className="h-4 w-4" />قضية جديدة</Button> : undefined} />{dueReminders.length > 0 && <button onClick={() => setPage('hearings')} className="w-full text-right mb-5 rounded-2xl border border-amber-200 bg-amber-50 p-4 flex items-center gap-3 text-amber-900"><div className="h-10 w-10 rounded-xl grid place-items-center bg-amber-100"><BellRing className="h-5 w-5" /></div><div><p className="font-semibold text-sm">لديك {dueReminders.length} تذكير جلسة مستحق الآن</p><p className="text-xs mt-1">راجع الجلسات المجدولة وسجّل النتيجة أو الإجراء اللازم.</p></div><ChevronLeft className="mr-auto h-4 w-4" /></button>}<div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4"><Card className="border-0 shadow-sm"><CardContent className="p-5 flex justify-between"><div><p className="text-sm text-muted-foreground">القضايا النشطة</p><p className="text-3xl font-bold text-[#153a36] mt-2">{activeCases.length}</p><p className="text-xs text-muted-foreground mt-2">تشمل الجديدة والمعلقة</p></div><div className="h-11 w-11 rounded-xl grid place-items-center bg-[#edf4f1] text-[#1b6258]"><BriefcaseBusiness className="h-5 w-5" /></div></CardContent></Card><Card className="border-0 shadow-sm"><CardContent className="p-5 flex justify-between"><div><p className="text-sm text-muted-foreground">الجلسات القادمة</p><p className="text-3xl font-bold text-[#153a36] mt-2">{upcoming.length}</p><p className="text-xs text-muted-foreground mt-2">المواعيد المجدولة</p></div><div className="h-11 w-11 rounded-xl grid place-items-center bg-amber-50 text-amber-700"><CalendarClock className="h-5 w-5" /></div></CardContent></Card><Card className="border-0 shadow-sm"><CardContent className="p-5 flex justify-between"><div><p className="text-sm text-muted-foreground">المهام المتأخرة</p><p className="text-3xl font-bold text-[#153a36] mt-2">{overdue.length}</p><p className="text-xs text-muted-foreground mt-2">تحتاج إلى إجراء</p></div><div className="h-11 w-11 rounded-xl grid place-items-center bg-rose-50 text-rose-700"><BellRing className="h-5 w-5" /></div></CardContent></Card><Card className="border-0 shadow-sm"><CardContent className="p-5 flex justify-between"><div><p className="text-sm text-muted-foreground">فريق المكتب</p><p className="text-3xl font-bold text-[#153a36] mt-2">{team.filter(i => i.is_active).length}</p><p className="text-xs text-muted-foreground mt-2">أعضاء نشطون</p></div><div className="h-11 w-11 rounded-xl grid place-items-center bg-blue-50 text-blue-700"><Users className="h-5 w-5" /></div></CardContent></Card></div><div className="grid xl:grid-cols-[1.2fr_.8fr] gap-5 mt-6"><Card className="border-0 shadow-sm"><CardHeader><div className="flex justify-between"><div><CardTitle className="text-lg text-[#153a36]">الجلسات القادمة</CardTitle><CardDescription>مرتبة حسب الموعد</CardDescription></div><Button variant="ghost" size="sm" onClick={() => setPage('hearings')}>عرض الكل<ChevronLeft className="h-4 w-4" /></Button></div></CardHeader><CardContent>{upcoming.length ? <div className="divide-y">{upcoming.map(item => <div className="py-4 flex gap-3" key={item.id}><div className="w-12 rounded-xl bg-[#edf4f1] text-[#1b6258] text-center py-2"><p className="font-bold">{new Intl.DateTimeFormat('ar-QA', { day: 'numeric' }).format(new Date(item.hearing_at))}</p><p className="text-[10px]">{new Intl.DateTimeFormat('ar-QA', { month: 'short' }).format(new Date(item.hearing_at))}</p></div><div className="flex-1"><p className="font-semibold text-sm text-[#153a36]">{caseById(item.case_id)?.title || 'قضية مرتبطة'}</p><p className="text-xs text-muted-foreground mt-1">{item.court_name || 'المحكمة غير محددة'} · {dateLabel(item.hearing_at)}</p></div><Badge variant="outline" className={tone(item.status)}>{hearingStatusLabel(item.status)}</Badge></div>)}</div> : <Empty icon={CalendarClock} title="لا توجد جلسات" text="أضف جلسة مرتبطة بقضية لبدء المتابعة." action={<Button variant="outline" onClick={() => setModal('hearing')}>جدولة جلسة</Button>} />}</CardContent></Card><Card className="border-0 shadow-sm bg-[#103b35] text-white"><CardHeader><CardTitle className="text-white flex gap-2"><Sparkles className="h-5 w-5 text-[#e8c377]" />مساعد المذكرات</CardTitle><CardDescription className="text-emerald-50/70">مسودات منظمة مع مصادر موثقة.</CardDescription></CardHeader><CardContent><p className="text-sm leading-7 text-emerald-50/85">حلّل الوقائع، راجع المسائل القانونية، وأنشئ مسودة دفاع قابلة للتحرير والمراجعة قبل أي اعتماد.</p><div className="mt-4 rounded-xl bg-white/10 p-3 text-xs leading-5">المخرج أداة دعم للمحامي ولا يمثل رأياً قانونياً نهائياً أو ضماناً لنتيجة.</div><Button className="w-full mt-5 bg-[#e8c377] text-[#153a36] hover:bg-[#f0d18a]" onClick={() => setPage('assistant')}>فتح مساحة المذكرة<ChevronLeft className="h-4 w-4" /></Button></CardContent></Card></div><div className="grid lg:grid-cols-2 gap-5 mt-6"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#153a36]">مهام مفتوحة</CardTitle></CardHeader><CardContent>{tasks.filter(i => i.status !== 'completed').length ? <div className="space-y-3">{tasks.filter(i => i.status !== 'completed').slice(0, 5).map(task => <div className="p-3 border rounded-xl flex gap-3" key={task.id}><button onClick={() => closeTask(task)} className="h-5 w-5 mt-0.5 rounded-full border-2 border-[#6b9b91] hover:bg-[#1b6258]" /><div className="flex-1"><p className="text-sm font-medium text-[#153a36]">{task.title}</p><p className={`text-xs mt-1 ${isOverdue(task.due_at, task.status) ? 'text-rose-600' : 'text-muted-foreground'}`}>{task.due_at ? `الاستحقاق: ${dateLabel(task.due_at)}` : 'دون موعد'}</p></div></div>)}</div> : <Empty icon={ClipboardCheck} title="لا توجد مهام مفتوحة" text="أنشئ مهمة ووزعها على فريق المكتب." />}</CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#153a36]">توزيع حالات القضايا</CardTitle></CardHeader><CardContent><div className="h-56">{charts.status.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={charts.status}><CartesianGrid vertical={false} stroke="#e7eeeb" strokeDasharray="3 3" /><XAxis dataKey="name" tickLine={false} axisLine={false} fontSize={11} /><YAxis allowDecimals={false} tickLine={false} axisLine={false} /><Tooltip /><Bar dataKey="value" fill="#21685e" radius={[7, 7, 0, 0]} /></BarChart></ResponsiveContainer> : <Empty icon={FolderKanban} title="لا توجد بيانات" text="تظهر المؤشرات تلقائياً عند تسجيل القضايا." />}</div></CardContent></Card></div></>;
  const casesPage = <><Title eyebrow="ملف القضايا" title="القضايا والمتابعة" text="إدارة مركزية للقضية والعميل والمحامي المسؤول والمحكمة والحالة الإجرائية." action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('case')}><Plus className="h-4 w-4" />قضية جديدة</Button> : undefined} />{cases.length ? <Card className="border-0 shadow-sm overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-sm"><thead className="bg-[#f4f7f5] text-muted-foreground"><tr>{['رقم القضية', 'العنوان والعميل', 'المحامي المسؤول', 'المحكمة', 'الحالة'].map(h => <th key={h} className="text-right p-4 font-medium">{h}</th>)}</tr></thead><tbody className="divide-y">{cases.map(item => <tr key={item.id} className="hover:bg-[#f8fbfa]"><td className="p-4 font-mono text-xs text-[#1b6258]">{item.case_number}</td><td className="p-4"><p className="font-semibold text-[#153a36]">{item.title}</p><p className="text-xs text-muted-foreground mt-1">{clientById(item.client_id)?.full_name || 'عميل غير محدد'} · {item.type}</p></td><td className="p-4 text-muted-foreground">{memberById(item.responsible_lawyer_id)?.display_name || 'غير مخصص'}</td><td className="p-4 text-muted-foreground">{item.court_name || '—'}</td><td className="p-4"><Badge variant="outline" className={tone(item.status)}>{caseStatusLabel(item.status)}</Badge></td></tr>)}</tbody></table></div></Card> : <Empty icon={BriefcaseBusiness} title="ابدأ بالقضية الأولى" text={practitioner ? 'أضف العميل ثم أنشئ قضية واربطها بالمحامي المسؤول.' : 'لا توجد قضايا مخصصة للمراجعة حالياً.'} action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('case')}>إضافة قضية</Button> : undefined} />}</>;
  const clientsPage = <><Title eyebrow="سجل العملاء" title="العملاء والاتصالات" text="ملفات موحّدة للعملاء تربط القضايا والمستندات وسجل التواصل." action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('client')}><Plus className="h-4 w-4" />عميل جديد</Button> : undefined} />{clients.length ? <div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-4">{clients.map(item => { const latest = communications.find(record => record.client_id === item.id); return <Card key={item.id} className="border-0 shadow-sm"><CardContent className="p-5"><div className="flex justify-between"><div className="h-10 w-10 rounded-xl grid place-items-center bg-[#edf4f1] text-[#1b6258] font-bold">{item.full_name.charAt(0)}</div><Badge variant="outline">{item.kind === 'company' ? 'شركة' : 'فرد'}</Badge></div><p className="font-bold text-[#153a36] mt-4">{item.full_name}</p><p className="text-sm text-muted-foreground mt-1" dir="ltr">{item.phone || item.email || 'لا توجد وسيلة اتصال'}</p><div className="border-t mt-4 pt-3 flex justify-between text-xs text-muted-foreground"><span>{item.national_id || 'رقم غير مسجل'}</span><span>{cases.filter(i => i.client_id === item.id).length} قضايا</span></div>{latest ? <p className="text-xs text-muted-foreground mt-3 leading-5 line-clamp-2">آخر متابعة: {latest.subject}</p> : <p className="text-xs text-muted-foreground mt-3">لا توجد متابعة مسجلة.</p>}<Button variant="ghost" size="sm" className="mt-3 text-[#1b6258]" onClick={() => { setSelectedClientId(item.id); setModal('communication'); }}>إضافة متابعة<ChevronLeft className="h-4 w-4" /></Button></CardContent></Card>; })}</div> : <Empty icon={Users} title="لا يوجد عملاء" text={practitioner ? 'أنشئ ملف العميل قبل بدء إجراءات القضية أو الأرشفة.' : 'لا توجد ملفات عملاء يمكنك متابعتها حالياً.'} action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('client')}>إضافة عميل</Button> : undefined} />}</>;
  const hearingsPage = <><Title eyebrow="تقويم القضاء" title="الجلسات والتذكيرات" text="جدولة الجلسات وربطها بالقضية مع تفاصيل المحكمة والتنبيه قبل الموعد." action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('hearing')}><Plus className="h-4 w-4" />جدولة جلسة</Button> : undefined} />{hearings.length ? <div className="space-y-3">{hearings.map(item => <Card key={item.id} className="border-0 shadow-sm"><CardContent className="p-4 flex flex-col sm:flex-row gap-4 sm:items-center"><div className="w-16 text-center rounded-xl py-2 bg-[#edf4f1] text-[#1b6258]"><p className="font-bold text-xl">{new Intl.DateTimeFormat('ar-QA', { day: 'numeric' }).format(new Date(item.hearing_at))}</p><p className="text-[10px]">{new Intl.DateTimeFormat('ar-QA', { month: 'short', year: 'numeric' }).format(new Date(item.hearing_at))}</p></div><div className="flex-1"><p className="font-semibold text-[#153a36]">{caseById(item.case_id)?.title || 'قضية مرتبطة'}</p><p className="text-sm text-muted-foreground mt-1">{item.court_name || 'المحكمة غير محددة'} · {dateLabel(item.hearing_at)}</p>{item.outcome && <p className="text-xs mt-2 p-2 rounded-lg bg-slate-50">النتيجة: {item.outcome}</p>}</div><div className="flex flex-wrap gap-2 items-center"><Badge variant="outline" className={tone(item.status)}>{hearingStatusLabel(item.status)}</Badge>{item.reminder_at && <BellRing className="h-4 w-4 text-[#b58524]" />}{practitioner && item.status === 'scheduled' && <Button size="sm" variant="outline" onClick={() => { setSelectedHearing(item); setModal('outcome'); }}>تسجيل النتيجة</Button>}</div></CardContent></Card>)}</div> : <Empty icon={CalendarClock} title="لا توجد جلسات مجدولة" text="أضف جلسة مرتبطة بقضية لمتابعة المواعيد والتنبيهات." action={<Button className="bg-[#0d3b36]" onClick={() => setModal('hearing')}>جدولة جلسة</Button>} />}</>;
  const tasksPage = <><Title eyebrow="إدارة العمل" title="المهام والتوزيع" text="إسناد العمل القانوني حسب الأولوية وموعد الإنجاز والمسؤول." action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('task')}><Plus className="h-4 w-4" />مهمة جديدة</Button> : undefined} />{tasks.length ? <div className="grid lg:grid-cols-2 gap-4">{tasks.map(task => <Card key={task.id} className="border-0 shadow-sm"><CardContent className="p-5 flex gap-4"><button disabled={task.status === 'completed'} onClick={() => closeTask(task)} className={`h-6 w-6 shrink-0 mt-0.5 rounded-full border-2 grid place-items-center ${task.status === 'completed' ? 'bg-emerald-600 text-white border-emerald-600' : 'border-[#6b9b91] hover:bg-[#1b6258]'}`}>{task.status === 'completed' && <CheckCircle2 className="h-4 w-4" />}</button><div className="flex-1"><div className="flex justify-between gap-2"><p className={`font-semibold ${task.status === 'completed' ? 'line-through text-muted-foreground' : 'text-[#153a36]'}`}>{task.title}</p><Badge variant="outline">{task.priority === 'urgent' ? 'عاجلة' : task.priority === 'high' ? 'عالية' : task.priority === 'medium' ? 'متوسطة' : 'منخفضة'}</Badge></div>{task.description && <p className="text-sm text-muted-foreground mt-2">{task.description}</p>}<div className="flex gap-3 mt-4 text-xs text-muted-foreground"><span>{memberById(task.assigned_to)?.display_name || 'غير مسند'}</span><span>{caseById(task.case_id)?.case_number || 'مهمة عامة'}</span><span className={isOverdue(task.due_at, task.status) ? 'text-rose-600 font-medium' : ''}>{task.due_at ? dateLabel(task.due_at) : 'دون موعد'}</span></div></div></CardContent></Card>)}</div> : <Empty icon={ClipboardCheck} title="لا توجد مهام" text="أنشئ مهمة وأسندها إلى فريق المكتب." action={<Button className="bg-[#0d3b36]" onClick={() => setModal('task')}>إضافة مهمة</Button>} />}</>;
  const docsPage = <><Title eyebrow="أرشيف آمن" title="المستندات والملفات" text="رفع المستندات الخاصة بالقضايا والعملاء ضمن مساحة تخزين معزولة للمكتب." action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('doc')}><UploadCloud className="h-4 w-4" />رفع مستند</Button> : undefined} />{docs.length ? <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4">{docs.map(item => <Card key={item.id} className="border-0 shadow-sm"><CardContent className="p-5"><div className="flex justify-between"><div className="h-10 w-10 rounded-xl grid place-items-center bg-[#fff8e8] text-[#ae7f1e]"><FileText className="h-5 w-5" /></div><Badge variant="outline">{item.category}</Badge></div><p dir="ltr" className="font-semibold text-[#153a36] truncate mt-4">{item.file_name}</p><p className="text-xs text-muted-foreground mt-2">{caseById(item.case_id)?.case_number || clientById(item.client_id)?.full_name || 'ملف عام'}</p><p className="text-xs text-muted-foreground mt-4">أضيف في {dateLabel(item.created_at)}</p></CardContent></Card>)}</div> : <Empty icon={FileText} title="لا توجد مستندات" text={practitioner ? 'ارفع ملفاً واربطه بقضية أو عميل لحفظه في الأرشيف.' : 'لا توجد مستندات متاحة للمراجعة حالياً.'} action={practitioner ? <Button className="bg-[#0d3b36]" onClick={() => setModal('doc')}>رفع مستند</Button> : undefined} />}</>;
  const teamPage = <><Title eyebrow="تنظيم الفريق" title="المحامون والموظفون" text="توزيع القضايا وقياس عبء العمل وإنشاء دعوات محددة بالدور." action={manager ? <Button className="bg-[#0d3b36]" onClick={() => setModal('invite')}><UserPlus className="h-4 w-4" />دعوة عضو</Button> : undefined} />{team.length ? <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4">{team.map(item => <Card key={item.id} className="border-0 shadow-sm"><CardContent className="p-5"><div className="flex justify-between"><div className="h-11 w-11 rounded-xl grid place-items-center bg-[#edf4f1] text-[#1b6258] font-bold text-lg">{item.display_name.charAt(0)}</div><Badge variant="outline" className={item.role === 'manager' ? 'bg-[#fff8e8] border-[#e8c377] text-[#8d6515]' : ''}>{roleLabel(item.role)}</Badge></div><p className="font-bold text-[#153a36] mt-4">{item.display_name || 'عضو جديد'}</p><p className="text-xs text-muted-foreground mt-1" dir="ltr">{item.email || '—'}</p><div className="flex justify-between border-t mt-4 pt-3 text-xs"><span className="text-muted-foreground">العمل النشط</span><span className="font-semibold text-[#1b6258]">{cases.filter(c => c.responsible_lawyer_id === item.id && ['new', 'active', 'on_hold', 'appeal'].includes(c.status)).length} قضايا</span></div></CardContent></Card>)}</div> : <Empty icon={UserPlus} title="الفريق لا يزال فارغاً" text="أضف المحامين والموظفين باستخدام دعوات مقيّدة بالدور." />}</>;
  const assistantPage = <><Title eyebrow="بحث وصياغة" title="مساعد المذكرات القانونية" text="تحليل للوقائع، مقترحات للدفوع، وأسئلة استكمال ومسودة قابلة للتحرير مع مراجع وسوابق موثقة." /><div className="grid xl:grid-cols-[.9fr_1.1fr] gap-5"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#153a36] flex gap-2"><Sparkles className="h-5 w-5 text-[#b58524]" />طلب المساعدة</CardTitle><CardDescription>يعمل Grok من الخادم فقط. كل ناتج يحتاج مراجعة محامٍ قبل الاعتماد.</CardDescription></CardHeader><CardContent className="space-y-4"><div className="space-y-2"><Label>القضية المرتبطة</Label><select className={inputClass} value={assistantCase} onChange={e => setAssistantCase(e.target.value)}><option value="none">بحث عام غير مرتبط بقضية</option>{cases.map(item => <option value={item.id} key={item.id}>{item.case_number} — {item.title}</option>)}</select></div><div className="space-y-2"><Label>الوقائع أو الطلب</Label><Textarea value={assistantText} onChange={e => setAssistantText(e.target.value)} className="min-h-64 leading-7" placeholder="اكتب الوقائع والطلبات والإجراء القائم وما تحتاجه من المساعد…" /></div><Button disabled={generate.isPending || !practitioner} onClick={runAssistant} className="w-full h-11 bg-[#0d3b36]">{generate.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}{generate.isPending ? 'يجري إعداد المسودة…' : 'تحليل وإعداد مسودة'}</Button>{!practitioner && <p className="text-xs bg-amber-50 text-amber-700 p-3 rounded-lg">هذه المساحة مخصصة للمحامين ومدير المكتب.</p>}<p className="text-xs leading-5 text-muted-foreground">تقتصر السوابق المعروضة على الأحكام الموثقة في قاعدة المعرفة. تحقّق دائماً من النصوص السارية قبل الاستناد إليها أو إيداع أي مستند.</p></CardContent></Card><div>{assistantResult ? <div className="space-y-5"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#153a36]">ملخص التحليل</CardTitle></CardHeader><CardContent><p className="text-sm leading-8">{assistantResult.summary}</p><p className="mt-5 p-3 rounded-xl bg-amber-50 border border-amber-100 text-xs leading-6 text-amber-800"><ShieldCheck className="inline h-4 w-4 ml-1" />{assistantResult.limitations}</p></CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#153a36]">مسودة أولية للمذكرة</CardTitle></CardHeader><CardContent><Textarea value={assistantResult.draft} onChange={e => setAssistantResult({ ...assistantResult, draft: e.target.value })} className="min-h-[360px] leading-8 text-sm" /><p className="text-xs text-muted-foreground mt-3">حرر النص ثم انسخه إلى ملف المذكرة بعد المراجعة المهنية.</p></CardContent></Card><div className="grid md:grid-cols-2 gap-5"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#153a36]">الدفوع المقترحة</CardTitle></CardHeader><CardContent className="space-y-3">{assistantResult.proposedDefences.map((item, index) => <div key={index} className="border-r-2 border-[#e8c377] pr-3"><div className="flex justify-between gap-2"><p className="font-semibold text-sm">{item.heading}</p><Badge variant="outline" className="text-[10px]">قوة {item.strength}</Badge></div><p className="text-xs leading-6 text-muted-foreground mt-1">{item.argument}</p></div>)}</CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#153a36]">أسئلة يلزم استكمالها</CardTitle></CardHeader><CardContent><ol className="list-decimal list-inside space-y-2 text-sm text-muted-foreground">{assistantResult.clarificationQuestions.map((item, index) => <li key={index}>{item}</li>)}</ol></CardContent></Card></div><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#153a36]">المصادر المستشهد بها</CardTitle></CardHeader><CardContent>{assistantResult.citations.length ? <div className="space-y-3">{assistantResult.citations.map(source => <a key={source.id} href={source.url} target="_blank" rel="noreferrer" className="block p-3 rounded-xl bg-[#f4f7f5] hover:bg-[#eaf3ef]"><p className="font-semibold text-sm text-[#1b6258]">{source.title}</p><p className="text-xs text-muted-foreground mt-1">{source.officialNumber || 'مصدر رسمي'}</p><p className="text-xs text-muted-foreground mt-2 line-clamp-2">{source.excerpt}</p></a>)}</div> : <p className="text-sm text-muted-foreground">لم يُعتمد مصدر في هذه النتيجة؛ تحقق من النقص في الوقائع والمراجع.</p>}</CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-base text-[#153a36]">سوابق وأحكام مماثلة</CardTitle></CardHeader><CardContent>{assistantResult.similarPrecedents.length ? <div className="space-y-3">{assistantResult.similarPrecedents.map(precedent => <a key={precedent.id} href={precedent.url} target="_blank" rel="noreferrer" className="block p-3 rounded-xl border hover:bg-[#f8fbfa]"><div className="flex justify-between gap-3"><p className="font-semibold text-sm text-[#153a36]">{precedent.title}</p><Badge variant="outline" className="shrink-0 text-[10px]">صلة {Math.round(precedent.relevanceScore * 100)}%</Badge></div><p className="text-xs text-muted-foreground mt-1">{precedent.courtName} · {precedent.referenceNumber || 'مرجع غير منشور'} · {precedent.decidedOn || '—'}</p><p className="text-xs text-muted-foreground mt-2 line-clamp-2">{precedent.summary}</p></a>)}</div> : <div className="text-sm text-muted-foreground leading-6">لا توجد سابقة موثقة مطابقة في قاعدة المعرفة حالياً. يمكن متابعة البحث من بوابة الميزان الرسمية قبل الاستناد إلى أي حكم.</div>}</CardContent></Card></div> : <Empty icon={Gavel} title="ابدأ من وقائع محددة" text="ستظهر هنا المسائل القانونية والدفوع والأسئلة والمسودة والمراجع والسابقة المعتمدة." />}</div></div></>;
  const sourcesPage = <><Title eyebrow="قاعدة المعرفة" title="المصادر القانونية الموثقة" text="سجل للمصادر الرسمية وروابطها، مع بحث ضمن النصوص المستوردة في النظام." /><Card className="border-0 shadow-sm"><CardContent className="p-5"><div className="relative"><Search className="absolute right-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pr-9" value={search} onChange={e => runSearch(e.target.value)} placeholder="ابحث داخل النصوص القانونية المستوردة…" /></div>{search.length >= 3 && <div className="mt-4 space-y-3">{searchResults.length ? searchResults.map(item => <a key={item.id} className="block border rounded-xl p-4 hover:bg-[#f8fbfa]" href={item.legal_sources?.source_url} target="_blank" rel="noreferrer"><p className="font-semibold text-sm text-[#153a36]">{item.legal_sources?.title}</p><p className="text-xs text-muted-foreground mt-1">{item.heading || 'نص قانوني'}</p><p className="text-sm leading-6 mt-2 line-clamp-3">{item.body}</p></a>) : <p className="text-sm text-muted-foreground py-2">لا توجد نتائج مطابقة في النصوص المستوردة.</p>}</div>}</CardContent></Card><div className="grid md:grid-cols-2 xl:grid-cols-4 gap-4 mt-5">{sources.map(item => <Card key={item.id} className="border-0 shadow-sm"><CardContent className="p-5"><div className="flex justify-between"><div className="h-9 w-9 rounded-xl grid place-items-center bg-[#edf4f1] text-[#1b6258]"><BookOpenText className="h-4 w-4" /></div><Badge variant="outline">{item.source_type === 'constitution' ? 'دستور' : 'قانون'}</Badge></div><p className="font-semibold text-sm leading-6 text-[#153a36] mt-4">{item.title}</p><p className="text-xs text-muted-foreground mt-2">{item.official_number || 'مرجع موثق'} · {item.issued_on || '—'}</p><a className="inline-flex text-xs font-semibold text-[#1b6258] mt-4" href={item.source_url} target="_blank" rel="noreferrer">فتح المصدر الرسمي<ChevronLeft className="h-3 w-3" /></a></CardContent></Card>)}</div></>;
  const reportsPage = <><Title eyebrow="مؤشرات المكتب" title="التقارير والتحليلات" text="متابعة مرئية لحالات القضايا ونوع العمل وأداء المكتب العام." action={<select aria-label="النطاق الزمني للتقرير" className="h-10 rounded-lg border bg-white px-3 text-sm" value={reportRange} onChange={event => setReportRange(event.target.value)}><option value="all">كل الفترات</option><option value="30">آخر 30 يوماً</option><option value="90">آخر 90 يوماً</option><option value="365">آخر 12 شهراً</option></select>} /><p className="text-xs text-muted-foreground -mt-3 mb-5">يعتمد النطاق على تاريخ فتح القضية؛ يعرض التقرير حالياً {reportCases.length} قضية ضمن النطاق المحدد.</p><div className="grid lg:grid-cols-2 gap-5"><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#153a36]">القضايا حسب الحالة</CardTitle></CardHeader><CardContent><div className="h-72">{charts.status.length ? <ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={charts.status} dataKey="value" nameKey="name" innerRadius={58} outerRadius={96} paddingAngle={3}>{charts.status.map((_, index) => <Cell key={index} fill={['#1e695f', '#cf9d31', '#547aaf', '#9d6aac', '#d26666'][index % 5]} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer> : <Empty icon={FolderKanban} title="لا توجد بيانات في هذا النطاق" text="غيّر الفترة أو أضف قضايا جديدة ليظهر التحليل." />}</div></CardContent></Card><Card className="border-0 shadow-sm"><CardHeader><CardTitle className="text-lg text-[#153a36]">القضايا حسب النوع</CardTitle></CardHeader><CardContent><div className="h-72">{charts.type.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={charts.type} layout="vertical"><CartesianGrid horizontal={false} stroke="#e7eeeb" strokeDasharray="3 3" /><XAxis type="number" allowDecimals={false} axisLine={false} tickLine={false} /><YAxis type="category" dataKey="name" width={72} axisLine={false} tickLine={false} /><Tooltip /><Bar dataKey="value" fill="#c9962b" radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer> : <Empty icon={FolderKanban} title="لا توجد بيانات في هذا النطاق" text="غيّر الفترة أو سجّل نوع القضية لظهور التوزيع." />}</div></CardContent></Card></div><Card className="border-0 shadow-sm mt-5"><CardContent className="grid sm:grid-cols-3 gap-4 p-5 text-center">{[['القضايا المغلقة', reportCases.length ? Math.round(reportCases.filter(i => i.status === 'closed').length / reportCases.length * 100) : 0, '%'], ['إنجاز المهام', tasks.length ? Math.round(tasks.filter(i => i.status === 'completed').length / tasks.length * 100) : 0, '%'], ['جلسات قادمة', upcoming.length, '']].map(([label, value, suffix]) => <div className="rounded-xl bg-[#f4f7f5] p-5" key={label as string}><p className="text-2xl font-bold text-[#1b6258]">{value as number}{suffix as string}</p><p className="text-xs text-muted-foreground mt-1">{label as string}</p></div>)}</CardContent></Card></>;
  const content: Record<Page, ReactNode> = { dashboard, cases: casesPage, hearings: hearingsPage, clients: clientsPage, tasks: tasksPage, documents: docsPage, team: teamPage, assistant: assistantPage, sources: sourcesPage, reports: reportsPage };
  const switchPage = (next: Page) => { setPage(next); setMobileMenu(false); };
  const drawer = <nav className="space-y-1">{nav.map(item => { const Icon = item.icon; return <button key={item.id} className={`w-full h-11 flex items-center gap-3 px-3 rounded-xl text-sm ${page === item.id ? 'bg-[#e9f2ef] text-[#145348] font-semibold' : 'text-[#5d716c] hover:bg-[#f4f7f5]'}`} onClick={() => switchPage(item.id)}><Icon className={`h-4 w-4 ${page === item.id ? 'text-[#b58524]' : ''}`} />{item.label}</button>; })}</nav>;
  return <div dir="rtl" className="min-h-screen bg-[#f4f7f5]"><aside className="hidden lg:flex fixed inset-y-0 right-0 w-72 bg-white border-l border-[#e5ece9] z-30 flex-col"><div className="p-6"><Brand /></div><div className="px-3 flex-1">{drawer}</div><div className="p-4 border-t"><div className="rounded-xl bg-[#f4f7f5] p-3 flex gap-3 items-center"><div className="h-9 w-9 rounded-full bg-[#0d3b36] text-[#e8c377] grid place-items-center font-semibold">{profile.display_name.charAt(0)}</div><div className="min-w-0 flex-1"><p className="text-sm font-semibold truncate text-[#153a36]">{profile.display_name}</p><p className="text-[11px] text-muted-foreground">{roleLabel(profile.role)}</p></div><button className="p-1.5 text-muted-foreground hover:text-rose-600" onClick={() => supabase.auth.signOut()}><LogOut className="h-4 w-4" /></button></div></div></aside><header className="lg:hidden sticky top-0 z-30 h-16 bg-white/95 backdrop-blur border-b px-4 flex items-center justify-between"><button className="p-2" onClick={() => setMobileMenu(true)}><Menu className="h-5 w-5" /></button><Brand compact /><span className="text-xs text-muted-foreground">{nav.find(i => i.id === page)?.label}</span></header>{mobileMenu && <div className="fixed inset-0 z-50 lg:hidden"><div className="absolute inset-0 bg-[#092a26]/40" onClick={() => setMobileMenu(false)} /><div className="absolute inset-y-0 right-0 w-72 bg-white p-4 shadow-2xl flex flex-col"><div className="flex justify-between items-center mb-5"><Brand /><button className="p-2" onClick={() => setMobileMenu(false)}><X className="h-5 w-5" /></button></div><div className="flex-1">{drawer}</div><Button variant="outline" onClick={() => supabase.auth.signOut()}><LogOut className="h-4 w-4" />تسجيل الخروج</Button></div></div>}<main className="lg:mr-72"><div className="max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">{content[page]}</div></main>
  {modal === 'client' && <Modal title="إضافة عميل" onClose={() => setModal(null)}><form className="grid sm:grid-cols-2 gap-4" onSubmit={e => add('client', e)}><div className="sm:col-span-2 space-y-2"><Label>الاسم أو اسم الشركة</Label><Input name="name" required /></div><div className="space-y-2"><Label>النوع</Label><select name="kind" className={inputClass}><option value="individual">فرد</option><option value="company">شركة</option></select></div><div className="space-y-2"><Label>رقم الهوية / السجل</Label><Input name="id_number" /></div><div className="space-y-2"><Label>الهاتف</Label><Input name="phone" dir="ltr" /></div><div className="space-y-2"><Label>البريد</Label><Input name="email" dir="ltr" type="email" /></div><div className="sm:col-span-2 space-y-2"><Label>ملاحظات</Label><Textarea name="notes" /></div><div className="sm:col-span-2 flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => setModal(null)}>إلغاء</Button><Button className="bg-[#0d3b36]">حفظ العميل</Button></div></form></Modal>}
  {modal === 'communication' && <Modal title="إضافة متابعة للعميل" onClose={() => setModal(null)}><form className="grid sm:grid-cols-2 gap-4" onSubmit={addCommunication}><div className="sm:col-span-2 space-y-2"><Label>العميل</Label><select name="client" className={inputClass} defaultValue={selectedClientId} required>{clients.map(item => <option key={item.id} value={item.id}>{item.full_name}</option>)}</select></div><div className="space-y-2"><Label>نوع التواصل</Label><select name="channel" className={inputClass} defaultValue="phone"><option value="phone">اتصال هاتفي</option><option value="email">بريد إلكتروني</option><option value="meeting">اجتماع</option><option value="whatsapp">واتساب</option><option value="other">أخرى</option></select></div><div className="space-y-2"><Label>وقت المتابعة</Label><Input name="occurred_at" type="datetime-local" defaultValue={dateValue(0)} required /></div><div className="sm:col-span-2 space-y-2"><Label>موضوع المتابعة</Label><Input name="subject" required placeholder="مثال: مراجعة المستندات المطلوبة" /></div><div className="sm:col-span-2 space-y-2"><Label>تفاصيل وإجراء لاحق</Label><Textarea name="content" className="min-h-28" placeholder="ما الذي تم التواصل بشأنه؟ وما الإجراء التالي؟" /></div><div className="sm:col-span-2 flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => setModal(null)}>إلغاء</Button><Button className="bg-[#0d3b36]">حفظ المتابعة</Button></div></form></Modal>}
  {modal === 'case' && <Modal title="تسجيل قضية جديدة" onClose={() => setModal(null)}>{clients.length ? <form className="grid sm:grid-cols-2 gap-4" onSubmit={e => add('case', e)}><div className="space-y-2"><Label>رقم القضية</Label><Input name="number" required placeholder="2026/1234" /></div><div className="space-y-2"><Label>النوع</Label><select name="type" className={inputClass}><option value="civil">مدنية</option><option value="commercial">تجارية</option><option value="criminal">جنائية</option><option value="labor">عمالية</option><option value="family">أسرة</option><option value="administrative">إدارية</option><option value="other">أخرى</option></select></div><div className="sm:col-span-2 space-y-2"><Label>عنوان القضية</Label><Input name="title" required /></div><div className="space-y-2"><Label>العميل</Label><select name="client" className={inputClass} required><option value="">اختر العميل</option>{clients.map(item => <option key={item.id} value={item.id}>{item.full_name}</option>)}</select></div><div className="space-y-2"><Label>المحامي المسؤول</Label><select name="lawyer" className={inputClass} defaultValue={profile.id}>{team.filter(i => ['manager', 'lawyer'].includes(i.role)).map(item => <option key={item.id} value={item.id}>{item.display_name}</option>)}</select></div><div className="space-y-2"><Label>المحكمة</Label><Input name="court" /></div><div className="sm:col-span-2 space-y-2"><Label>ملخص الوقائع</Label><Textarea name="description" /></div><div className="sm:col-span-2 flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => setModal(null)}>إلغاء</Button><Button className="bg-[#0d3b36]">تسجيل القضية</Button></div></form> : <Empty icon={Users} title="يلزم إضافة عميل أولاً" text="القضية يجب أن ترتبط بعميل محفوظ في النظام." action={<Button onClick={() => { setModal(null); setPage('clients'); }}>الانتقال إلى العملاء</Button>} />}</Modal>}
  {modal === 'hearing' && <Modal title="جدولة جلسة" onClose={() => setModal(null)}>{cases.length ? <form className="grid sm:grid-cols-2 gap-4" onSubmit={e => add('hearing', e)}><div className="sm:col-span-2 space-y-2"><Label>القضية</Label><select name="case" className={inputClass} required><option value="">اختر القضية</option>{cases.map(item => <option key={item.id} value={item.id}>{item.case_number} — {item.title}</option>)}</select></div><div className="space-y-2"><Label>موعد الجلسة</Label><Input name="at" type="datetime-local" defaultValue={dateValue()} required /></div><div className="space-y-2"><Label>نوع الجلسة</Label><Input name="type" placeholder="مرافعة / تأجيل" /></div><div className="space-y-2"><Label>المحكمة</Label><Input name="court" /></div><div className="space-y-2"><Label>القاعة</Label><Input name="room" /></div><div className="sm:col-span-2 space-y-2"><Label>ملاحظات</Label><Textarea name="notes" /></div><div className="sm:col-span-2 flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => setModal(null)}>إلغاء</Button><Button className="bg-[#0d3b36]">حفظ الجلسة</Button></div></form> : <Empty icon={BriefcaseBusiness} title="يلزم تسجيل قضية أولاً" text="الجلسات تُدار في سياق قضية مرتبطة." />}</Modal>}
  {modal === 'outcome' && selectedHearing && <Modal title="تسجيل نتيجة الجلسة" onClose={() => { setModal(null); setSelectedHearing(null); }}><form className="space-y-4" onSubmit={recordOutcome}><div className="rounded-xl bg-[#f4f7f5] p-3 text-sm"><p className="font-semibold text-[#153a36]">{caseById(selectedHearing.case_id)?.title || 'قضية مرتبطة'}</p><p className="text-xs text-muted-foreground mt-1">{dateLabel(selectedHearing.hearing_at)}</p></div><div className="space-y-2"><Label>حالة الجلسة</Label><select name="status" className={inputClass} defaultValue="held"><option value="held">عُقدت</option><option value="postponed">أُجلت</option><option value="cancelled">أُلغيت</option></select></div><div className="space-y-2"><Label>النتيجة أو القرار</Label><Textarea name="outcome" required className="min-h-32" placeholder="سجل ما حدث في الجلسة والإجراء المطلوب تالياً…" /></div><div className="flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => { setModal(null); setSelectedHearing(null); }}>إلغاء</Button><Button className="bg-[#0d3b36]">حفظ النتيجة</Button></div></form></Modal>}
  {modal === 'task' && <Modal title="إنشاء مهمة" onClose={() => setModal(null)}><form className="grid sm:grid-cols-2 gap-4" onSubmit={e => add('task', e)}><div className="sm:col-span-2 space-y-2"><Label>عنوان المهمة</Label><Input name="title" required /></div><div className="space-y-2"><Label>إسناد إلى</Label><select name="member" className={inputClass} defaultValue={profile.id}>{team.map(item => <option key={item.id} value={item.id}>{item.display_name}</option>)}</select></div><div className="space-y-2"><Label>الأولوية</Label><select name="priority" className={inputClass} defaultValue="medium"><option value="low">منخفضة</option><option value="medium">متوسطة</option><option value="high">عالية</option><option value="urgent">عاجلة</option></select></div><div className="space-y-2"><Label>القضية</Label><select name="case" className={inputClass}><option value="">مهمة عامة</option>{cases.map(item => <option key={item.id} value={item.id}>{item.case_number}</option>)}</select></div><div className="space-y-2"><Label>الموعد</Label><Input name="due" type="datetime-local" defaultValue={dateValue(2)} /></div><div className="sm:col-span-2 space-y-2"><Label>التفاصيل</Label><Textarea name="description" /></div><div className="sm:col-span-2 flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => setModal(null)}>إلغاء</Button><Button className="bg-[#0d3b36]">إنشاء المهمة</Button></div></form></Modal>}
  {modal === 'doc' && <Modal title="رفع مستند" onClose={() => setModal(null)}><form className="grid sm:grid-cols-2 gap-4" onSubmit={e => add('doc', e)}><div className="sm:col-span-2 space-y-2"><Label>الملف</Label><Input name="file" type="file" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg" required /></div><div className="space-y-2"><Label>التصنيف</Label><select name="category" className={inputClass}><option value="court_filing">مذكرة قضائية</option><option value="power_of_attorney">وكالة</option><option value="contract">عقد</option><option value="evidence">دليل</option><option value="identity">هوية</option><option value="memo">مذكرة</option><option value="other">أخرى</option></select></div><div className="space-y-2"><Label>القضية</Label><select name="case" className={inputClass}><option value="">غير مرتبط</option>{cases.map(item => <option key={item.id} value={item.id}>{item.case_number}</option>)}</select></div><div className="sm:col-span-2 space-y-2"><Label>العميل</Label><select name="client" className={inputClass}><option value="">غير مرتبط</option>{clients.map(item => <option key={item.id} value={item.id}>{item.full_name}</option>)}</select></div><p className="sm:col-span-2 text-xs text-muted-foreground">يجب ربط المستند بقضية أو عميل. التخزين خاص بالمكتب.</p><div className="sm:col-span-2 flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => setModal(null)}>إلغاء</Button><Button className="bg-[#0d3b36]">رفع المستند</Button></div></form></Modal>}
  {modal === 'invite' && <Modal title="دعوة عضو إلى المكتب" onClose={() => setModal(null)}><form className="space-y-4" onSubmit={e => add('invite', e)}><div className="space-y-2"><Label>البريد الإلكتروني</Label><Input name="email" type="email" dir="ltr" required /></div><div className="space-y-2"><Label>الدور</Label><select name="role" className={inputClass}><option value="lawyer">محامٍ</option><option value="employee">موظف</option></select></div><p className="text-xs text-muted-foreground">سيتم إنشاء رابط دعوة فريد ونسخه للحافظة لمشاركته مع العضو.</p><div className="flex justify-end gap-3"><Button type="button" variant="outline" onClick={() => setModal(null)}>إلغاء</Button><Button className="bg-[#0d3b36]">إنشاء رابط الدعوة</Button></div></form></Modal>}
  </div>;
}
